architecture.h4_f:
|
msg = CBOR{v:1, ટેક્સ્ટ, જવાબ_ને, મોકલેલ_એટ}
ct = AES-GCM-256-એનક્રિપ્ટ(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
|
pt = CBOR{v:1, ટેક્સ્ટ, reply_to?, thread_id?, ઉલ્લેખો?, send_at}
ct = AES-GCM-256-એનક્રિપ્ટ(રૂમ_કી, નોન્સ, pt, aad=hex(room_id))
વાયર = CBOR{
  v: 1,
  સિફરટેક્સ્ટ: હેક્સ(સીટી), // ચલ લંબાઈ
  નોન્સ: હેક્સ(12 બી),
  પ્રેષક_સ્યુડો: હેક્સ(16 બી),
  send_at: unix_ms
}

cryptoWire.h5_f:
|
બાહ્ય = CBOR{
  સ્ત્રોત_નોડ: hex32,
  લક્ષ્ય_વપરાશકર્તા: int64,
  આંતરિક_સિફર ટેક્સ્ટ: બાઇટ્સ,
  આંતરિક_નોન્સ: બાઇટ્સ,
  send_at: unix_ms
}
sig = Ed25519-સાઇન(સ્રોત_પ્રિવ, બાહ્ય)
POST /ફેડરેશન/ડિલિવર { એન્વેલપ: બાહ્ય, સિગ: હેક્સ64 }

